import org.apache.commons.cli.Option;
import org.apache.commons.cli.OptionBuilder;

public class M8Probe {

    static void cases() throws Exception {
        // Typical input: short option only
        probe("typical_short_option", () -> {
            return OptionBuilder.create("a");
        });

        // Short option with long option
        probe("short_and_long_option", () -> {
            OptionBuilder.withLongOpt("arg-name");
            return OptionBuilder.create("a");
        });

        // Short option with description
        probe("short_option_with_description", () -> {
            OptionBuilder.withDescription("This is a description.");
            return OptionBuilder.create("d");
        });

        // Short option with argument
        probe("short_option_with_arg", () -> {
            OptionBuilder.hasArg();
            return OptionBuilder.create("x");
        });

        // Short option with argument name
        probe("short_option_with_arg_name", () -> {
            OptionBuilder.hasArg().withArgName("file");
            return OptionBuilder.create("f");
        });

        // Short option required
        probe("short_option_required", () -> {
            OptionBuilder.isRequired();
            return OptionBuilder.create("r");
        });

        // Short option with type
        probe("short_option_with_type", () -> {
            OptionBuilder.withType(String.class);
            return OptionBuilder.create("t");
        });

        // Short option with optional argument
        probe("short_option_with_optional_arg", () -> {
            OptionBuilder.hasOptionalArg();
            return OptionBuilder.create("o");
        });

        // Short option with value separator
        probe("short_option_with_value_separator", () -> {
            OptionBuilder.withValueSeparator('=');
            return OptionBuilder.create("p");
        });

        // Empty short option (should throw IllegalArgumentException)
        probe("empty_short_option", () -> {
            return OptionBuilder.create("");
        });

        // Null short option (should throw IllegalArgumentException)
        probe("null_short_option", () -> {
            return OptionBuilder.create(null);
        });

        // Short option with multiple arguments
        probe("short_option_with_multiple_args", () -> {
            OptionBuilder.hasArgs();
            return OptionBuilder.create("m");
        });

        // Short option with specific number of arguments
        probe("short_option_with_specific_num_args", () -> {
            OptionBuilder.hasArgs(2);
            return OptionBuilder.create("n");
        });

        // Complex configuration
        probe("complex_configuration", () -> {
            OptionBuilder.withLongOpt("verbose")
                    .withDescription("Enable verbose output")
                    .hasArg(false)
                    .isRequired(false)
                    .withType(Boolean.class);
            return OptionBuilder.create("v");
        });

        // Another complex configuration
        probe("another_complex_configuration", () -> {
            OptionBuilder.withLongOpt("property")
                    .withDescription("Set a system property")
                    .hasArgs(2)
                    .withArgName("key=value")
                    .withValueSeparator('=');
            return OptionBuilder.create("D");
        });

        // Calling create multiple times to ensure state reset
        probe("multiple_calls_first", () -> {
            OptionBuilder.withDescription("First option");
            return OptionBuilder.create("1");
        });
        probe("multiple_calls_second", () -> {
            // If reset didn't happen, this might inherit description from previous call
            return OptionBuilder.create("2");
        });

        // Short option with special character (valid for Option)
        probe("special_char_short_option", () -> {
            return OptionBuilder.create("?");
        });

        // Short option with a digit
        probe("digit_short_option", () -> {
            return OptionBuilder.create("1");
        });

        // Short option with a space (should throw IllegalArgumentException if Option doesn't allow it)
        probe("space_short_option", () -> {
            return OptionBuilder.create(" ");
        });
    }
}

