        probe("typical_long_text_multiple_breaks_start_middle", () -> formatter.findWrapPos("This is a longer text that needs to be wrapped multiple times.", 20, 15));

        // Explicit line breaks
        probe("explicit_newline", () -> formatter.findWrapPos("Line1\nLine2", 20, 0));
        probe("explicit_tab", () -> formatter.findWrapPos("Line1\tLine2", 20, 0));
        probe("explicit_newline_at_width_boundary", () -> formatter.findWrapPos("This is a line\nwith a newline.", 15, 0));
        probe("explicit_tab_at_width_boundary", () -> formatter.findWrapPos("This is a line\twith a tab.", 15, 0));
        probe("explicit_newline_after_width", () -> formatter.findWrapPos("This is a line with a newline after the width.", 10, 0));

        // Word longer than width (chop)
        probe("long_word_chop", () -> formatter.findWrapPos("Thisisalongwordthatwillbechopped.", 10, 0));
        probe("long_word_chop_with_space_after", () -> formatter.findWrapPos("Thisisalongword that will be chopped.", 10, 0));
        probe("long_word_chop_start_middle", () -> formatter.findWrapPos("Some text andthenthisisalongwordthatwillbechopped.", 10, 15));

        // Edge cases for width
        probe("width_equals_text_length", () -> formatter.findWrapPos("Short text", 10, 0));
        probe("width_greater_than_text_length", () -> formatter.findWrapPos("Short text", 20, 0));
        probe("width_one", () -> formatter.findWrapPos("abc def", 1, 0));

        // Edge cases for startPos
        probe("startPos_zero", () -> formatter.findWrapPos("This is a test.", 10, 0));
        probe("startPos_end_of_text", () -> formatter.findWrapPos("This is a test.", 10, 15));
        probe("startPos_just_before_end", () -> formatter.findWrapPos("This is a test.", 10, 14));

        // No suitable wrap point (returns -1)
        probe("no_wrap_point_fits", () -> formatter.findWrapPos("Short", 10, 0));
        probe("no_wrap_point_fits_after_startPos", () -> formatter.findWrapPos("This is a test.", 10, 10));

        // Invalid arguments (expecting IllegalArgumentException)
        probe("null_text", () -> formatter.findWrapPos(null, 10, 0));
        probe("negative_width", () -> formatter.findWrapPos("text", -5, 0));
        probe("zero_width", () -> formatter.findWrapPos("text", 0, 0));
        probe("startPos_negative", () -> formatter.findWrapPos("text", 10, -1));
        probe("startPos_too_large", () -> formatter.findWrapPos("text", 10, 5));
    }

    // Helper method to simulate the probe runner
    private static void probe(String label, java.util.concurrent.Callable<Object> callable) throws Exception {
        try {
            Object result = callable.call();
            System.out.println(label + ": " + result);
        } catch (Throwable t) {
            System.out.println(label + ": Throws " + t.getClass().getSimpleName() + " - " + t.getMessage());
        }
    }
}

