            StringBuffer sb = new StringBuffer();
            formatter.renderWrappedText(sb, 20, 0, "This is a short line.");
            return sb.toString();
        });

        // Case 2: Basic wrapping with text longer than the width, causing a wrap
        probe("single_line_long_wrap", () -> {
            StringBuffer sb = new StringBuffer();
            formatter.renderWrappedText(sb, 10, 0, "This is a very long line that needs to be wrapped.");
            return sb.toString();
        });

        // Case 3: Text with multiple words, wrapping at word boundaries
        probe("multi_word_wrap", () -> {
            StringBuffer sb = new StringBuffer();
            formatter.renderWrappedText(sb, 15, 0, "This text has multiple words and should wrap nicely.");
            return sb.toString();
        });

        // Case 4: Text with no spaces, forcing a break mid-word if width is too small
        probe("no_spaces_wrap", () -> {
            StringBuffer sb = new StringBuffer();
            formatter.renderWrappedText(sb, 5, 0, "supercalifragilisticexpialidocious");
            return sb.toString();
        });

        // Case 5: Empty text
        probe("empty_text", () -> {
            StringBuffer sb = new StringBuffer();
            formatter.renderWrappedText(sb, 20, 0, "");
            return sb.toString();
        });

        // Case 6: Null text
        probe("null_text", () -> {
            StringBuffer sb = new StringBuffer();
            formatter.renderWrappedText(sb, 20, 0, null);
            return sb.toString();
        });

        // Case 7: Text with leading/trailing spaces
        probe("text_with_padding", () -> {
            StringBuffer sb = new StringBuffer();
            formatter.renderWrappedText(sb, 10, 0, "  Padded text  ");
            return sb.toString();
        });

        // Case 8: Text with newlines already present (should be handled by the wrapper, not just passed through)
        probe("text_with_newlines", () -> {
            StringBuffer sb = new StringBuffer();
            formatter.renderWrappedText(sb, 15, 0, "First line.\nSecond line.\nThird line.");
            return sb.toString();
        });

        // Case 9: First line exactly at width limit, subsequent lines indented
        probe("first_line_exact_width_indent", () -> {
            StringBuffer sb = new StringBuffer();
            formatter.renderWrappedText(sb, 10, 4, "Exactly ten chars. This is a very long second line that needs to be indented and wrapped.");
            return sb.toString();
        });

        // Case 10: Subsequent lines with a tab stop
        probe("subsequent_lines_indent", () -> {
            StringBuffer sb = new StringBuffer();
            formatter.renderWrappedText(sb, 20, 5, "This is the first line of text. This is the second line which should be indented. And here is a third line.");
            return sb.toString();
        });

        // Case 11: Zero tab stop for subsequent lines
        probe("zero_tab_stop", () -> {
            StringBuffer sb = new StringBuffer();
            formatter.renderWrappedText(sb, 20, 0, "First line. Second line with no indent. Third line also no indent.");
            return sb.toString();
        });

        // Case 12: Large tab stop, making subsequent lines very short
        probe("large_tab_stop", () -> {
            StringBuffer sb = new StringBuffer();
            formatter.renderWrappedText(sb, 20, 15, "First line. Subsequent lines will be very short due to large indent.");
            return sb.toString();
        });

        // Case 13: Width of 1
        probe("width_one", () -> {
            StringBuffer sb = new StringBuffer();
            formatter.renderWrappedText(sb, 1, 0, "abcde");
            return sb.toString();
        });

        // Case 14: Width of 1 with indent
        probe("width_one_indent", () -> {
            StringBuffer sb = new StringBuffer();
            formatter.renderWrappedText(sb, 1, 2, "abcde");
            return sb.toString();
        });

        // Case 15: Text containing only spaces
        probe("text_only_spaces", () -> {
            StringBuffer sb = new StringBuffer();
            formatter.renderWrappedText(sb, 10, 0, "     ");
            return sb.toString();
        });

        // Case 16: Text with special characters
        probe("special_chars", () -> {
            StringBuffer sb = new StringBuffer();
            formatter.renderWrappedText(sb, 15, 0, "Text with !@#$%^&*()_+-=[]{}\\|;:'\",.<>/? characters.");
            return sb.toString();
        });

        // Case 17: Long text with varying word lengths and indent
        probe("long_text_varying_words_indent", () -> {
            StringBuffer sb = new StringBuffer();
            formatter.renderWrappedText(sb, 30, 8, "This is a very long piece of text that contains words of different lengths, some short, some quite long, to thoroughly test the wrapping logic with indentation.");
            return sb.toString();
        });

        // Case 18: Null StringBuffer (should throw IllegalArgumentException)
        probe("null_stringbuffer", () -> {
            formatter.renderWrappedText(null, 20, 0, "Some text.");
            return "Should throw IllegalArgumentException"; // This line won't be reached
        });

        // Case 19: Negative width (should throw IllegalArgumentException based on documentation "Must be a positive integer")
        probe("negative_width", () -> {
            StringBuffer sb = new StringBuffer();
            formatter.renderWrappedText(sb, -5, 0, "Some text.");
            return "Should throw IllegalArgumentException"; // This line won't be reached
        });

        // Case 20: Zero width (should throw IllegalArgumentException based on documentation "Must be a positive integer")
        probe("zero_width", () -> {
            StringBuffer sb = new StringBuffer();
            formatter.renderWrappedText(sb, 0, 0, "Some text.");
            return "Should throw IllegalArgumentException"; // This line won't be reached
        });
    }

    // Helper method to simulate the probe runner
    private static void probe(String label, java.util.concurrent.Callable<Object> callable) throws Exception {
        // In a real probe runner, this would execute the callable and record its output/exceptions.
        // For this exercise, we just call it to ensure it compiles and to indicate the intent.
        System.out.println("Running probe: " + label);
        try {
            Object result = callable.call();
            System.out.println("Result: " + result);
        } catch (Throwable t) {
            System.out.println("Exception: " + t.getClass().getSimpleName() + " - " + t.getMessage());
        }
    }
}

