import org.apache.commons.codec.EncoderException;

class DoubleMetaphoneProbe {

    static void cases() throws Exception {
        DoubleMetaphone metaphone = new DoubleMetaphone();

        // Typical inputs
        probe("Typical: Smith vs. Smythe (primary)", () -> metaphone.isDoubleMetaphoneEqual("Smith", "Smythe", false));
        probe("Typical: Smith vs. Smythe (alternate)", () -> metaphone.isDoubleMetaphoneEqual("Smith", "Smythe", true));
        probe("Typical: Schmidt vs. Schmitt (primary)", () -> metaphone.isDoubleMetaphoneEqual("Schmidt", "Schmitt", false));
        probe("Typical: Schmidt vs. Schmitt (alternate)", () -> metaphone.isDoubleMetaphoneEqual("Schmidt", "Schmitt", true));
        probe("Typical: Phone vs. Fone (primary)", () -> metaphone.isDoubleMetaphoneEqual("Phone", "Fone", false));
        probe("Typical: Phone vs. Fone (alternate)", () -> metaphone.isDoubleMetaphoneEqual("Phone", "Fone", true));

        // Identical strings
        probe("Identical: Hello vs. Hello (primary)", () -> metaphone.isDoubleMetaphoneEqual("Hello", "Hello", false));
        probe("Identical: Hello vs. Hello (alternate)", () -> metaphone.isDoubleMetaphoneEqual("Hello", "Hello", true));

        // Different strings, no phonetic similarity
        probe("Different: Cat vs. Dog (primary)", () -> metaphone.isDoubleMetaphoneEqual("Cat", "Dog", false));
        probe("Different: Cat vs. Dog (alternate)", () -> metaphone.isDoubleMetaphoneEqual("Cat", "Dog", true));

        // Empty strings
        probe("Empty: Empty vs. Empty (primary)", () -> metaphone.isDoubleMetaphoneEqual("", "", false));
        probe("Empty: Empty vs. Empty (alternate)", () -> metaphone.isDoubleMetaphoneEqual("", "", true));
        probe("Empty: Empty vs. Non-empty (primary)", () -> metaphone.isDoubleMetaphoneEqual("", "Test", false));
        probe("Empty: Non-empty vs. Empty (primary)", () -> metaphone.isDoubleMetaphoneEqual("Test", "", false));

        // Null inputs (should throw IllegalArgumentException)
        probe("Null: value1 is null", () -> {
            try {
                return metaphone.isDoubleMetaphoneEqual(null, "Test", false);
            } catch (IllegalArgumentException e) {
                return e.getClass().getSimpleName();
            }
        });
        probe("Null: value2 is null", () -> {
            try {
                return metaphone.isDoubleMetaphoneEqual("Test", null, false);
            } catch (IllegalArgumentException e) {
                return e.getClass().getSimpleName();
            }
        });
        probe("Null: both null", () -> {
            try {
                return metaphone.isDoubleMetaphoneEqual(null, null, false);
            } catch (IllegalArgumentException e) {
                return e.getClass().getSimpleName();
            }
        });

        // Case sensitivity (Double Metaphone is generally case-insensitive)
        probe("Case: smith vs. SMYTHE (primary)", () -> metaphone.isDoubleMetaphoneEqual("smith", "SMYTHE", false));
        probe("Case: SMITH vs. smythe (alternate)", () -> metaphone.isDoubleMetaphoneEqual("SMITH", "smythe", true));

        // Strings with special characters (should be handled by cleanInput)
        probe("Special chars: O'Malley vs. OMalley (primary)", () -> metaphone.isDoubleMetaphoneEqual("O'Malley", "OMalley", false));
        probe("Special chars: O'Malley vs. OMalley (alternate)", () -> metaphone.isDoubleMetaphoneEqual("O'Malley", "OMalley", true));
    }
}

