import java.nio.CharBuffer;

class StringUtilsTest {
    static void cases() throws Exception {
        // Null inputs
        probe("null, null", () -> StringUtils.equals(null, null));
        probe("null, \"abc\"", () -> StringUtils.equals(null, "abc"));
        probe("\"abc\", null", () -> StringUtils.equals("abc", null));

        // Identical strings
        probe("\"abc\", \"abc\"", () -> StringUtils.equals("abc", "abc"));
        probe("\"\", \"\"", () -> StringUtils.equals("", ""));
        probe("\" \", \" \"", () -> StringUtils.equals(" ", " "));
        probe("\"123\", \"123\"", () -> StringUtils.equals("123", "123"));

        // Different strings (case-sensitive)
        probe("\"abc\", \"ABC\"", () -> StringUtils.equals("abc", "ABC"));
        probe("\"abc\", \"abd\"", () -> StringUtils.equals("abc", "abd"));
        probe("\"abc\", \"abcd\"", () -> StringUtils.equals("abc", "abcd"));
        probe("\"abcd\", \"abc\"", () -> StringUtils.equals("abcd", "abc"));

        // CharSequence implementations
        probe("StringBuilder, StringBuilder (equal)", () -> StringUtils.equals(new StringBuilder("abc"), new StringBuilder("abc")));
        probe("StringBuilder, StringBuilder (different)", () -> StringUtils.equals(new StringBuilder("abc"), new StringBuilder("ABC")));
        probe("String, StringBuilder (equal)", () -> StringUtils.equals("abc", new StringBuilder("abc")));
        probe("String, StringBuilder (different)", () -> StringUtils.equals("abc", new StringBuilder("ABC")));
        probe("CharBuffer, CharBuffer (equal)", () -> StringUtils.equals(CharBuffer.wrap("test"), CharBuffer.wrap("test")));
        probe("CharBuffer, CharBuffer (different)", () -> StringUtils.equals(CharBuffer.wrap("test"), CharBuffer.wrap("Test")));

        // Long strings
        String longStr1 = "Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.";
        String longStr2 = "Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.";
        String longStr3 = "Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqub.";
        probe("long string, long string (equal)", () -> StringUtils.equals(longStr1, longStr2));
        probe("long string, long string (different)", () -> StringUtils.equals(longStr1, longStr3));
    }
}

