import java.io.IOException;
import java.io.InputStream;
import java.util.Arrays;

class Base64InputStreamReadProbe {

    static void cases() throws Exception {
        // Typical inputs
        probe("decode_simple_string", () -> {
            String encoded = "SGVsbG8gV29ybGQ="; // "Hello World"
            InputStream is = new ByteArrayInputStream(encoded.getBytes());
            Base64InputStream b64is = new Base64InputStream(is, false);
            byte[] buffer = new byte[20];
            int bytesRead = b64is.read(buffer, 0, buffer.length);
            return new String(buffer, 0, bytesRead);
        });

        probe("encode_simple_string", () -> {
            String decoded = "Hello World";
            InputStream is = new ByteArrayInputStream(decoded.getBytes());
            Base64InputStream b64is = new Base64InputStream(is, true);
            byte[] buffer = new byte[20];
            int bytesRead = b64is.read(buffer, 0, buffer.length);
            return new String(buffer, 0, bytesRead);
        });

        probe("decode_multiple_reads", () -> {
            String encoded = "SGVsbG8gV29ybGQgYW5kIHNvbWUgZXh0cmEgdGV4dA=="; // "Hello World and some extra text"
            InputStream is = new ByteArrayInputStream(encoded.getBytes());
            Base64InputStream b64is = new Base64InputStream(is, false);
            byte[] buffer = new byte[5];
            StringBuilder result = new StringBuilder();
            int bytesRead;
            while ((bytesRead = b64is.read(buffer, 0, buffer.length)) != -1) {
                result.append(new String(buffer, 0, bytesRead));
            }
            return result.toString();
        });

        probe("encode_multiple_reads", () -> {
            String decoded = "This is a longer string to encode and read in parts.";
            InputStream is = new ByteArrayInputStream(decoded.getBytes());
