        // Blank inputs (expecting NumberFormatException)
        probe("empty string", () -> createNumber(""));
        probe("blank string space", () -> createNumber(" "));
        probe("blank string tab", () -> createNumber("\t"));

        // Invalid input: "--" pattern
        probe("invalid double dash", () -> createNumber("--"));
        probe("invalid double dash with number", () -> createNumber("--123"));

        // Integer parsing
        probe("integer zero", () -> createNumber("0"));
        probe("integer positive", () -> createNumber("123"));
        probe("integer negative", () -> createNumber("-45"));
        probe("integer max", () -> createNumber(String.valueOf(Integer.MAX_VALUE)));
        probe("integer min", () -> createNumber(String.valueOf(Integer.MIN_VALUE)));
        probe("integer just over max", () -> createNumber(String.valueOf((long) Integer.MAX_VALUE + 1))); // Should be Long
        probe("integer just under min", () -> createNumber(String.valueOf((long) Integer.MIN_VALUE - 1))); // Should be Long

        // Long parsing
        probe("long positive", () -> createNumber("123456789012345L"));
