        probe("long just under min (no suffix)", () -> createNumber(new BigInteger(String.valueOf(Long.MIN_VALUE)).subtract(BigInteger.ONE).toString())); // Should be BigInteger

        // Hexadecimal integers
        probe("hex positive", () -> createNumber("0xAF"));
        probe("hex negative", () -> createNumber("-0x10"));
        probe("hex zero", () -> createNumber("0x0"));
        probe("hex mixed case", () -> createNumber("0XaBcD"));

        // Float parsing
        probe("float positive", () -> createNumber("1.23f"));
        probe("float negative", () -> createNumber("-0.5F"));
        probe("float scientific", () -> createNumber("1.2e3f"));
        probe("float zero decimal", () -> createNumber("0.0f"));
