        probe("float small value", () -> createNumber("1.4E-45f"));

        // Double parsing
        probe("double positive", () -> createNumber("1.23D"));
        probe("double negative", () -> createNumber("-0.5d"));
        probe("double scientific", () -> createNumber("1.2e3")); // No suffix, should be Double
        probe("double zero decimal", () -> createNumber("0.0")); // No suffix, should be Double
        probe("double large value", () -> createNumber("1.7976931348623157E308"));
        probe("double small value", () -> createNumber("4.9E-324"));

        // BigDecimal parsing (fallback for precision)
        probe("bigdecimal large decimal", () -> createNumber("12345678901234567890.12345678901234567890"));
        probe("bigdecimal scientific precise", () -> createNumber("1.2345678901234567890E-20"));
        probe("bigdecimal float precision loss", () -> createNumber("0.123456789012345678901234567890123456789")); // Too precise for Float/Double
        probe("bigdecimal double precision loss", () -> createNumber("1.0000000000000001")); // Value that double cannot represent exactly

        // Numbers with only decimal point
        probe("decimal point only", () -> createNumber(".")); // Expect NumberFormatException
        probe("decimal point leading", () -> createNumber(".5")); // Should be Float/Double
        probe("decimal point trailing", () -> createNumber("123.")); // Should be Float/Double

        // Type suffix parsing
        probe("long suffix", () -> createNumber("123L"));
        probe("float suffix", () -> createNumber("1.2f"));
        probe("double suffix", () -> createNumber("1.2D"));

        // Invalid number formats
        probe("invalid text", () -> createNumber("abc"));
