        FastDateFormat fdfPatternUTCUS = FastDateFormat.getInstance("yyyy-MM-dd HH:mm:ss z", utcTimeZone, usLocale);

        // Calendar instances
        Calendar calEpoch = new GregorianCalendar(utcTimeZone);
        calEpoch.setTimeInMillis(0); // January 1, 1970, 00:00:00 GMT

        Calendar calSpecificDate = new GregorianCalendar(estTimeZone);
        calSpecificDate.set(2023, Calendar.OCTOBER, 27, 10, 30, 45); // October 27, 2023, 10:30:45 EST

        Calendar calSpecificDateUTC = new GregorianCalendar(utcTimeZone);
        calSpecificDateUTC.set(2023, Calendar.OCTOBER, 27, 10, 30, 45); // October 27, 2023, 10:30:45 UTC

        Calendar calWithDifferentTimeZone = new GregorianCalendar(TimeZone.getTimeZone("PST"));
        calWithDifferentTimeZone.set(2023, Calendar.OCTOBER, 27, 10, 30, 45); // October 27, 2023, 10:30:45 PST

        // StringBuffer instances
        StringBuffer bufEmpty = new StringBuffer();
        StringBuffer bufPrepopulated = new StringBuffer("Prefix: ");

        // --- Typical Inputs ---
