            return fdfDefault.format(calEpoch, buf).toString();
        });
        probe("T2: Pattern format, specific calendar, empty buffer", () -> {
            StringBuffer buf = new StringBuffer();
            return fdfPattern.format(calSpecificDate, buf).toString();
        });
        probe("T3: Pattern format, specific calendar, prepopulated buffer", () -> {
