            return fdfPattern.format(calSpecificDate, buf).toString(); // No direct way to make Calendar's TimeZone null
        });
        probe("E4: Empty pattern (FastDateFormat.getInstance should handle this, but testing format with it)", () -> {
            FastDateFormat fdfEmptyPattern = FastDateFormat.getInstance("");
            StringBuffer buf = new StringBuffer();
            return fdfEmptyPattern.format(calSpecificDate, buf).toString();
        });
        probe("E5: Complex pattern with various fields", () -> {
            FastDateFormat fdfComplex = FastDateFormat.getInstance("EEEE, MMMM dd, yyyy 'at' hh:mm:ss a zzz");
            StringBuffer buf = new StringBuffer();
            return fdfComplex.format(calSpecificDate, buf).toString();
        });
        probe("E6: Calendar with time before epoch (negative milliseconds)", () -> {
            Calendar calBeforeEpoch = new GregorianCalendar(utcTimeZone);
            calBeforeEpoch.setTimeInMillis(-1000); // December 31, 1969, 23:59:59 GMT
            StringBuffer buf = new StringBuffer();
            return fdfPatternUTC.format(calBeforeEpoch, buf).toString();
