            StringBuffer buf = new StringBuffer();
            return fdfPatternUTC.format(calMaxTime, buf).toString();
        });
        probe("E8: Re-using the same buffer for multiple formats", () -> {
            StringBuffer buf = new StringBuffer();
            fdfPattern.format(calEpoch, buf);
            buf.append(" | ");
            fdfPattern.format(calSpecificDate, buf);
            return buf.toString();
        });
    }
}

