            System.out.println("Result: " + result);
        } catch (Throwable t) {
            System.out.println("Exception: " + t.getClass().getSimpleName() + " - " + t.getMessage());
        }
    }

    public static void cases() throws Exception {
        // Case 1: Stop a running stopwatch
        probe("Stop a running stopwatch", () -> {
            StopWatch sw = new StopWatch();
            sw.start();
            Thread.sleep(10); // Simulate some time passing
            sw.stop();
            return sw.toString(); // Expecting a time value
        });

        // Case 2: Stop a suspended stopwatch
        probe("Stop a suspended stopwatch", () -> {
            StopWatch sw = new StopWatch();
            sw.start();
            Thread.sleep(10);
            sw.suspend();
            Thread.sleep(10); // Time while suspended
            sw.stop();
            return sw.toString(); // Expecting a time value (excluding suspended time)
        });

        // Case 3: Stop an unstarted stopwatch (should throw IllegalStateException)
        probe("Stop an unstarted stopwatch", () -> {
            StopWatch sw = new StopWatch();
            sw.stop(); // Should throw IllegalStateException
            return "Should not reach here";
        });

        // Case 4: Stop a stopped stopwatch (should throw IllegalStateException)
        probe("Stop a stopped stopwatch", () -> {
            StopWatch sw = new StopWatch();
            sw.start();
            sw.stop();
            sw.stop(); // Should throw IllegalStateException
            return "Should not reach here";
        });

        // Case 5: Stop a stopwatch after split
        probe("Stop a stopwatch after split", () -> {
            StopWatch sw = new StopWatch();
            sw.start();
            Thread.sleep(10);
            sw.split();
            Thread.sleep(10);
            sw.stop();
            return sw.toString(); // Expecting total time
        });

        // Case 6: Stop a stopwatch after unsplit
        probe("Stop a stopwatch after unsplit", () -> {
            StopWatch sw = new StopWatch();
            sw.start();
            Thread.sleep(10);
            sw.split();
            Thread.sleep(10);
            sw.unsplit();
            Thread.sleep(10);
            sw.stop();
            return sw.toString(); // Expecting total time
        });

        // Case 7: Stop a stopwatch and check getTime()
        probe("Stop a stopwatch and check getTime()", () -> {
            StopWatch sw = new StopWatch();
            sw.start();
            Thread.sleep(50);
            sw.stop();
            return sw.getTime() > 0; // Expecting a positive time
        });

        // Case 8: Stop a stopwatch and check toString() format
        probe("Stop a stopwatch and check toString() format", () -> {
            StopWatch sw = new StopWatch();
            sw.start();
            Thread.sleep(10);
            sw.stop();
            String result = sw.toString();
            // Basic check for format: contains "00:00:00.0"
            return result.matches("\\d{2}:\\d{2}:\\d{2}\\.\\d{3}");
        });

        // Case 9: Stop a stopwatch after multiple start/stop cycles (reset in between)
        probe("Stop after multiple start/stop cycles (with reset)", () -> {
            StopWatch sw = new StopWatch();
            sw.start();
            Thread.sleep(10);
            sw.stop();
            sw.reset();
            sw.start();
            Thread.sleep(10);
            sw.stop();
            return sw.getTime() > 0; // Expecting a positive time from the last cycle
        });

        // Case 10: Stop a stopwatch that was suspended multiple times
        probe("Stop a stopwatch suspended multiple times", () -> {
            StopWatch sw = new StopWatch();
            sw.start();
            Thread.sleep(5);
            sw.suspend();
            Thread.sleep(5);
            sw.resume();
            Thread.sleep(5);
            sw.suspend();
            Thread.sleep(5);
            sw.resume();
            Thread.sleep(5);
            sw.stop();
            return sw.getTime() > 0; // Expecting a positive time
        });

        // Case 11: Stop a stopwatch immediately after start
        probe("Stop immediately after start", () -> {
            StopWatch sw = new StopWatch();
            sw.start();
            sw.stop();
            return sw.getTime() >= 0; // Should be very close to 0 or 0
        });

        // Case 12: Stop a stopwatch after a very long run (simulated)
        probe("Stop after a very long run (simulated)", () -> {
            StopWatch sw = new StopWatch();
            sw.start();
            // Simulate a long run by setting internal time (not directly accessible, so rely on getTime)
            // This case primarily checks if stop handles large time values correctly.
            // We can't directly manipulate startTime, so we'll just let it run for a bit.
            Thread.sleep(100);
            sw.stop();
            return sw.getTime() > 90; // Expecting a time around 100ms
        });

        // Case 13: Stop a stopwatch that was split and then suspended
        probe("Stop after split then suspended", () -> {
            StopWatch sw = new StopWatch();
            sw.start();
            Thread.sleep(10);
            sw.split();
            Thread.sleep(10);
            sw.suspend();
            Thread.sleep(10);
            sw.stop();
            return sw.getTime() > 0; // Expecting total time excluding suspended
        });

        // Case 14: Stop a stopwatch that was suspended and then split
        probe("Stop after suspended then split", () -> {
            StopWatch sw = new StopWatch();
            sw.start();
            Thread.sleep(10);
            sw.suspend();
            Thread.sleep(10);
            sw.resume();
            Thread.sleep(10);
            sw.split();
            Thread.sleep(10);
            sw.stop();
            return sw.getTime() > 0; // Expecting total time
        });

        // Case 15: Stop a stopwatch and verify split time is invalidated (by checking getSplitTime throws exception)
        probe("Stop and verify split time invalidated", () -> {
            StopWatch sw = new StopWatch();
            sw.start();
            Thread.sleep(10);
            sw.split();
            Thread.sleep(10);
            sw.stop();
            try {
                sw.getSplitTime(); // Should throw IllegalStateException
                return "getSplitTime did not throw exception";
            } catch (IllegalStateException e) {
                return "getSplitTime threw IllegalStateException as expected";
            }
        });
    }
}

