import java.util.Calendar;
import java.util.TimeZone;
import java.util.Locale;

public class DurationFormatUtilsProbe {

    static void probe(String label, java.util.concurrent.Callable<Object> callable) {
        // Implementation of probe method is not relevant for this task.
        // It is a placeholder to satisfy the requirement of the output format.
        try {
            callable.call();
        } catch (Exception e) {
            // Handle exception for the probe
            System.err.println("Probe '" + label + "' threw an exception: " + e.getMessage());
        }
    }

    static void cases() throws Exception {
        // Typical duration: 1 year, 2 months, 3 days, 4 hours, 5 minutes, 6 seconds, 7 milliseconds
        Calendar start = Calendar.getInstance(TimeZone.getTimeZone("GMT"));
        start.set(2022, Calendar.JANUARY, 1, 0, 0, 0);
        start.set(Calendar.MILLISECOND, 0);

        Calendar end = Calendar.getInstance(TimeZone.getTimeZone("GMT"));
        end.set(2023, Calendar.MARCH, 4, 4, 5, 6);
        end.set(Calendar.MILLISECOND, 7);

        long startMillis = start.getTimeInMillis();
        long endMillis = end.getTimeInMillis();

        // Test case 1: Basic format with all units, no padding
        probe("Basic format, no padding", () -> DurationFormatUtils.formatPeriod(startMillis, endMillis, "y 'years,' M 'months,' d 'days,' H 'hours,' m 'minutes,' s 'seconds,' S 'milliseconds'", false, TimeZone.getTimeZone("GMT")));

        // Test case 2: Basic format with all units, with padding
        probe("Basic format, with padding", () -> DurationFormatUtils.formatPeriod(startMillis, endMillis, "yy 'years,' MM 'months,' dd 'days,' HH 'hours,' mm 'minutes,' ss 'seconds,' SSS 'milliseconds'", true, TimeZone.getTimeZone("GMT")));

        // Test case 3: Empty format string
        probe("Empty format string", () -> DurationFormatUtils.formatPeriod(startMillis, endMillis, "", false, TimeZone.getTimeZone("GMT")));

        // Test case 4: Null format string
        probe("Null format string", () -> DurationFormatUtils.formatPeriod(startMillis, endMillis, null, false, TimeZone.getTimeZone("GMT")));

        // Test case 5: Only years
        probe("Only years", () -> DurationFormatUtils.formatPeriod(startMillis, endMillis, "y", false, TimeZone.getTimeZone("GMT")));

        // Test case 6: Only months
        probe("Only months", () -> DurationFormatUtils.formatPeriod(startMillis, endMillis, "M", false, TimeZone.getTimeZone("GMT")));

        // Test case 7: Only days
        probe("Only days", () -> DurationFormatUtils.formatPeriod(startMillis, endMillis, "d", false, TimeZone.getTimeZone("GMT")));

        // Test case 8: Only hours
        probe("Only hours", () -> DurationFormatUtils.formatPeriod(startMillis, endMillis, "H", false, TimeZone.getTimeZone("GMT")));

        // Test case 9: Only minutes
        probe("Only minutes", () -> DurationFormatUtils.formatPeriod(startMillis, endMillis, "m", false, TimeZone.getTimeZone("GMT")));

        // Test case 10: Only seconds
        probe("Only seconds", () -> DurationFormatUtils.formatPeriod(startMillis, endMillis, "s", false, TimeZone.getTimeZone("GMT")));

        // Test case 11: Only milliseconds
        probe("Only milliseconds", () -> DurationFormatUtils.formatPeriod(startMillis, endMillis, "S", false, TimeZone.getTimeZone("GMT")));

        // Test case 12: startMillis > endMillis (should swap internally)
        probe("Start > End", () -> DurationFormatUtils.formatPeriod(endMillis, startMillis, "y 'years,' M 'months'", false, TimeZone.getTimeZone("GMT")));

        // Test case 13: Zero duration
        probe("Zero duration", () -> DurationFormatUtils.formatPeriod(startMillis, startMillis, "y 'years,' M 'months,' d 'days,' H 'hours,' m 'minutes,' s 'seconds,' S 'milliseconds'", false, TimeZone.getTimeZone("GMT")));

        // Test case 14: Different timezone (e.g., PST)
        probe("Different timezone (PST)", () -> DurationFormatUtils.formatPeriod(startMillis, endMillis, "y 'years,' M 'months,' d 'days'", false, TimeZone.getTimeZone("America/Los_Angeles")));

        // Test case 15: Leap year scenario (Feb 28 to Mar 1 in a leap year)
        Calendar leapStart = Calendar.getInstance(TimeZone.getTimeZone("GMT"));
        leapStart.set(2024, Calendar.FEBRUARY, 28, 0, 0, 0);
        leapStart.set(Calendar.MILLISECOND, 0);
        Calendar leapEnd = Calendar.getInstance(TimeZone.getTimeZone("GMT"));
        leapEnd.set(2024, Calendar.MARCH, 1, 0, 0, 0);
        leapEnd.set(Calendar.MILLISECOND, 0);
        probe("Leap year scenario (Feb 28 to Mar 1)", () -> DurationFormatUtils.formatPeriod(leapStart.getTimeInMillis(), leapEnd.getTimeInMillis(), "d 'days'", false, TimeZone.getTimeZone("GMT")));

        // Test case 16: Non-leap year scenario (Feb 28 to Mar 1 in a non-leap year)
        Calendar nonLeapStart = Calendar.getInstance(TimeZone.getTimeZone("GMT"));
        nonLeapStart.set(2023, Calendar.FEBRUARY, 28, 0, 0, 0);
        nonLeapStart.set(Calendar.MILLISECOND, 0);
        Calendar nonLeapEnd = Calendar.getInstance(TimeZone.getTimeZone("GMT"));
        nonLeapEnd.set(2023, Calendar.MARCH, 1, 0, 0, 0);
        nonLeapEnd.set(Calendar.MILLISECOND, 0);
        probe("Non-leap year scenario (Feb 28 to Mar 1)", () -> DurationFormatUtils.formatPeriod(nonLeapStart.getTimeInMillis(), nonLeapEnd.getTimeInMillis(), "d 'days'", false, TimeZone.getTimeZone("GMT")));

        // Test case 17: Format with quoted literals
        probe("Format with quoted literals", () -> DurationFormatUtils.formatPeriod(startMillis, endMillis, "'Duration is' y 'years and' M 'months'", false, TimeZone.getTimeZone("GMT")));

        // Test case 18: Format with mixed padding
        probe("Format with mixed padding", () -> DurationFormatUtils.formatPeriod(startMillis, endMillis, "y 'years,' MM 'months,' d 'days'", true, TimeZone.getTimeZone("GMT")));

        // Test case 19: Timezone null (should throw IllegalArgumentException)
        probe("Timezone null", () -> DurationFormatUtils.formatPeriod(startMillis, endMillis, "y", false, null));

        // Test case 20: Large duration (multiple years, months, etc.)
        Calendar veryLongStart = Calendar.getInstance(TimeZone.getTimeZone("GMT"));
        veryLongStart.set(1970, Calendar.JANUARY, 1, 0, 0, 0);
        veryLongStart.set(Calendar.MILLISECOND, 0);
        Calendar veryLongEnd = Calendar.getInstance(TimeZone.getTimeZone("GMT"));
        veryLongEnd.set(2050, Calendar.DECEMBER, 31, 23, 59, 59);
        veryLongEnd.set(Calendar.MILLISECOND, 999);
        probe("Very large duration", () -> DurationFormatUtils.formatPeriod(veryLongStart.getTimeInMillis(), veryLongEnd.getTimeInMillis(), "y 'years,' M 'months,' d 'days'", false, TimeZone.getTimeZone("GMT")));
    }
}

